CREATE TABLE books ("book_id" TEXT PRIMARY KEY,"source_file" TEXT,"source_book" TEXT,"sha256" TEXT,"grade" INTEGER,"semester" TEXT,"pdf_pages" INTEGER,"pages_with_chinese_text" INTEGER,"is_scanned" INTEGER,"duplicate_of" TEXT,"toc_pdf_pages" TEXT,"printed_to_pdf_offset" INTEGER,"version_evidence_pdf" TEXT,"publisher" TEXT,"version_note" TEXT,"toc_status" TEXT,"parse_status" TEXT);
CREATE TABLE chapters ("node_id" TEXT PRIMARY KEY,"book_id" TEXT REFERENCES books(book_id),"chapter_id" TEXT,"section_id" TEXT,"kind" TEXT,"title" TEXT,"printed_page" INTEGER,"pdf_page" INTEGER,"toc_pdf_page" INTEGER,"body_check" TEXT,"special" TEXT,"topic" TEXT);
CREATE TABLE sections ("node_id" TEXT PRIMARY KEY,"book_id" TEXT REFERENCES books(book_id),"chapter_id" TEXT REFERENCES chapters(node_id),"section_id" TEXT,"kind" TEXT,"title" TEXT,"printed_page" INTEGER,"pdf_page" INTEGER,"toc_pdf_page" INTEGER,"body_check" TEXT,"special" TEXT);
CREATE TABLE structure ("node_id" TEXT PRIMARY KEY,"book_id" TEXT REFERENCES books(book_id),"chapter_id" TEXT REFERENCES chapters(node_id),"section_id" TEXT REFERENCES sections(node_id),"kind" TEXT,"title" TEXT,"printed_page" INTEGER,"pdf_page" INTEGER,"toc_pdf_page" INTEGER,"body_check" TEXT,"special" TEXT,"topic" TEXT);
CREATE TABLE concepts ("knowledge_id" TEXT PRIMARY KEY,"name" TEXT,"book_id" TEXT REFERENCES books(book_id),"source_book" TEXT,"grade" INTEGER,"semester" TEXT,"chapter_id" TEXT REFERENCES chapters(node_id),"chapter" TEXT,"section_id" TEXT REFERENCES sections(node_id),"section" TEXT,"source_pages" TEXT,"category" TEXT,"definition" TEXT,"core_elements" TEXT,"formulas" TEXT,"conditions" TEXT,"intuition" TEXT,"prerequisites" TEXT,"related_knowledge" TEXT,"confusable_with" TEXT,"common_mistakes" TEXT,"example_ids" TEXT,"topics" TEXT,"source_status" TEXT,"confidence" TEXT,"provenance" TEXT,"intuition_source" TEXT,"special" TEXT,"optional_scope_notes" TEXT);
CREATE TABLE examples ("example_id" TEXT PRIMARY KEY,"source_type" TEXT,"book_id" TEXT REFERENCES books(book_id),"source_book" TEXT,"grade" INTEGER,"semester" TEXT,"chapter_id" TEXT REFERENCES chapters(node_id),"chapter" TEXT,"section_id" TEXT REFERENCES sections(node_id),"section" TEXT,"pdf_page" INTEGER,"printed_page" INTEGER,"original_label" TEXT,"problem_text" TEXT,"solution_text" TEXT,"answer" TEXT,"math_expressions" TEXT,"diagram_refs" TEXT,"knowledge_ids" TEXT,"key_steps" TEXT,"methods" TEXT,"common_mistakes" TEXT,"difficulty" TEXT,"extraction_status" TEXT,"evidence_images" TEXT,"source_anchor" TEXT,"verified_end_pdf" INTEGER,"evidence_window_pdf" TEXT,"topic_tags" TEXT,"mapping_source" TEXT,"content_provenance" TEXT,"notes" TEXT);
CREATE TABLE relationships ("relation_id" TEXT PRIMARY KEY,"from_id" TEXT REFERENCES concepts(knowledge_id),"to_id" TEXT REFERENCES concepts(knowledge_id),"relation_type" TEXT,"source_type" TEXT,"explanation" TEXT,"book_id" TEXT REFERENCES books(book_id),"source_book" TEXT,"chapter_id" TEXT REFERENCES chapters(node_id),"source_pages" TEXT);
CREATE TABLE occurrences ("book_id" TEXT REFERENCES books(book_id),"source_book" TEXT,"grade" INTEGER,"semester" TEXT,"chapter_id" TEXT REFERENCES chapters(node_id),"chapter" TEXT,"section_id" TEXT REFERENCES sections(node_id),"section" TEXT,"knowledge_id" TEXT REFERENCES concepts(knowledge_id),"pdf_page" INTEGER,"printed_page" INTEGER,"role" TEXT,"example_id" TEXT REFERENCES examples(example_id));
CREATE TABLE issues ("issue_id" TEXT PRIMARY KEY,"type" TEXT,"book_id" TEXT REFERENCES books(book_id),"source_book" TEXT,"pdf_page" INTEGER,"printed_page" INTEGER,"ref" TEXT,"reason" TEXT,"next_action" TEXT);
CREATE TABLE example_concepts(example_id TEXT NOT NULL REFERENCES examples(example_id),knowledge_id TEXT NOT NULL REFERENCES concepts(knowledge_id),PRIMARY KEY(example_id,knowledge_id));
CREATE TABLE concept_topics(knowledge_id TEXT NOT NULL REFERENCES concepts(knowledge_id),topic TEXT NOT NULL,PRIMARY KEY(knowledge_id,topic));
CREATE INDEX occ_ch ON occurrences(chapter_id,section_id,knowledge_id);
CREATE INDEX rel_target ON relationships(to_id,relation_type);
CREATE INDEX ex_by_concept ON example_concepts(knowledge_id);
CREATE INDEX ex_by_ch ON examples(chapter_id,section_id,extraction_status);
CREATE UNIQUE INDEX concept_name ON concepts(name);
CREATE VIEW verified_examples AS SELECT * FROM examples WHERE source_type='textbook_example' AND extraction_status='verified';
CREATE VIEW chapter_concepts AS SELECT DISTINCT o.chapter_id,o.knowledge_id,c.name,c.definition,c.formulas,c.source_status FROM occurrences o JOIN concepts c USING(knowledge_id);
CREATE VIEW prerequisites AS SELECT r.to_id AS knowledge_id,r.from_id AS prerequisite_id,c.name AS prerequisite,r.source_type,r.explanation FROM relationships r JOIN concepts c ON c.knowledge_id=r.from_id WHERE r.relation_type='prerequisite_of';
CREATE TABLE exam_papers(paper_id TEXT PRIMARY KEY,year INTEGER UNIQUE,region TEXT,original_path TEXT,sha256 TEXT UNIQUE,number_count INTEGER,payload TEXT);
CREATE TABLE exam_questions(question_id TEXT PRIMARY KEY,paper_id TEXT NOT NULL REFERENCES exam_papers,number INTEGER,original_number_label TEXT,stem_status TEXT,stem TEXT,checked_stem TEXT,checked_answer TEXT,study_ready INTEGER,method TEXT,approach TEXT,payload TEXT,UNIQUE(paper_id,number));
CREATE TABLE exam_knowledge_links(question_id TEXT NOT NULL REFERENCES exam_questions,knowledge_id TEXT NOT NULL REFERENCES concepts,role TEXT CHECK(role IN ('core','support')),reason TEXT,evidence_basis TEXT,PRIMARY KEY(question_id,knowledge_id));
CREATE INDEX exam_by_concept ON exam_knowledge_links(knowledge_id,role);
CREATE VIEW concept_exams AS SELECT c.chapter_id,c.knowledge_id,c.name,l.role,q.question_id,q.number,p.year,q.study_ready,q.method,l.reason,l.evidence_basis FROM concepts c JOIN exam_knowledge_links l USING(knowledge_id) JOIN exam_questions q USING(question_id) JOIN exam_papers p USING(paper_id);
CREATE VIEW checked_exam_questions AS SELECT * FROM exam_questions WHERE study_ready=1;
CREATE VIEW exam_textbook_examples AS SELECT DISTINCT l.question_id,l.knowledge_id,e.example_id FROM exam_knowledge_links l JOIN example_concepts ec USING(knowledge_id) JOIN verified_examples e USING(example_id);
